}

selector .product_meta a {
  color: #F7007A !important;
  font-weight: 700;
}

selector .product_meta a:hover {
  color: #00E5C4 !important;
}

/* Tabs / descripción */
selector .woocommerce-tabs {
  margin-top: 44px !important;
  padding: clamp(24px, 3vw, 38px);
  border-radius: 32px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.085), rgba(255, 255, 255, 0.04)),
    rgba(17, 17, 17, 0.58);
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 22px 56px rgba(0, 0, 0, 0.34);
}

selector .woocommerce-tabs ul.tabs {
  border-bottom: 1px solid rgba(255, 255, 255, 0.14) !important;
}

selector .woocommerce-tabs ul.tabs li {
  border-radius: 999px !important;
  background: rgba(255, 255, 255, 0.07) !important;
  border: 1px solid rgba(255, 255, 255, 0.14) !important;
}

selector .woocommerce-tabs ul.tabs li a {
  color: #FFFFFF !important;
  font-weight: 900 !important;
}

selector .woocommerce-tabs ul.tabs li.active {
  background: linear-gradient(135deg, rgba(0, 229, 196, 0.22), rgba(247, 0, 122, 0.16)) !important;
  border-color: rgba(0, 229, 196, 0.34) !important;
}

selector .woocommerce-Tabs-panel,
selector .woocommerce-Tabs-panel p,
selector .woocommerce-Tabs-panel li {
  color: #BFC4C2 !important;
  line-height: 1.75;
}

/* Títulos internos */
selector .woocommerce-Tabs-panel h2,
selector .related.products h2,
selector .upsells.products h2 {
  color: #FFFFFF !important;
  font-family: "Optima", "Optima LT Std", "Candara", "Segoe UI", Arial, sans-serif !important;
  font-weight: 400 !important;
  letter-spacing: -0.04em;
}

/* Productos relacionados */
selector .related.products,
selector .upsells.products {
  margin-top: 50px;
}

selector .related.products ul.products li.product,
selector .upsells.products ul.products li.product {
  padding: 20px !important;
  border-radius: 28px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.085), rgba(255, 255, 255, 0.04)),
    rgba(17, 17, 17, 0.62);
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 20px 48px rgba(0, 0, 0, 0.30);
}

selector ul.products li.product .woocommerce-loop-product__title {
  color: #FFFFFF !important;
  font-weight: 900;
}

selector ul.products li.product .price {
  color: #00E5C4 !important;
}

/* Responsive */
@media (max-width: 768px) {
  selector .product {
    padding: 22px 16px !important;
    border-radius: 26px;
  }

  selector div.product div.images,
  selector .woocommerce-product-gallery,
  selector div.product div.summary,
  selector .summary.entry-summary {
    border-radius: 24px;
  }

  selector .product_title,
  selector h1.product_title {
    font-size: clamp(1.9rem, 9vw, 2.8rem) !important;
    text-align: center;
  }

  selector .price,
  selector p.price {
    text-align: center;
  }

  selector form.cart {
    display: flex !important;
    flex-direction: column;
    gap: 12px;
    align-items: stretch;
  }

  selector .quantity input.qty {
    width: 100% !important;
  }

  selector button.single_add_to_cart_button,
  selector .single_add_to_cart_button {
    width: 100% !important;
  }

  selector .product_meta {
    text-align: center;
  }
}
